using System.Globalization; using System.Text.RegularExpressions; using System.Windows; using System.Windows.Controls; namespace WpfSemana02;
public partial class IngresoWindow:Window { public IngresoWindow(){InitializeComponent();cboConductor.ItemsSource=Datos.Conductores;cboCamion.ItemsSource=Datos.Camiones;cboProducto.ItemsSource=Datos.Productos;cboTipo.SelectedIndex=0;cboTurno.SelectedIndex=0;dpFecha.SelectedDate=DateTime.Today;}
private void Guardar_Click(object s,RoutedEventArgs e){if(cboConductor.SelectedItem is not Conductor conductor){Aviso("Seleccione un conductor registrado.");return;}if(cboCamion.SelectedItem is not Camion camion){Aviso("Seleccione un camión registrado.");return;}if(cboProducto.SelectedItem is not Producto producto){Aviso("Seleccione un producto registrado.");return;}var tipo=((ComboBoxItem)cboTipo.SelectedItem).Content.ToString()!;var num=txtNumero.Text.Trim().ToUpper();var ok=tipo=="DNI"?Regex.IsMatch(num,@"^\d{8}$"):tipo=="RUC"?Regex.IsMatch(num,@"^\d{11}$"):Regex.IsMatch(num,@"^EG\d{2}-\d{8}$");if(!ok){Aviso("Documento inválido. DNI: 8 dígitos, RUC: 11 dígitos, Guía: EG01-00000001.");return;}if(txtCliente.Text.Trim().Length<3){Aviso("Ingrese el cliente.");return;}if(!double.TryParse(txtPeso.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var peso)||peso<=0){Aviso("Ingrese un peso mayor que cero.");return;}if(camion.CapacidadKg>0&&peso>camion.CapacidadKg){Aviso("El peso supera la capacidad del camión.");return;}Datos.Ingresos.Add(new(){Id=Datos.SiguienteId(Datos.Ingresos,x=>x.Id),TipoDocumento=tipo,NumeroDocumento=num,Placa=camion.Placa,Turno=((ComboBoxItem)cboTurno.SelectedItem).Content.ToString()!,Conductor=conductor.Nombre,Cliente=txtCliente.Text.Trim(),FechaHora=dpFecha.SelectedDate??DateTime.Today,Producto=producto.Nombre,Peso=peso,Transporte=camion.Transportista});Datos.Guardar();MessageBox.Show("Ingreso registrado correctamente.","Proceso completado");Close();}private static void Aviso(string m)=>MessageBox.Show(m,"Validación",MessageBoxButton.OK,MessageBoxImage.Warning);}
